import { test, expect } from '@playwright/test';

test.describe('Timeout Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://your-application-url.com');
  });

  test('should display timeout error after 10 seconds', async ({ page }) => {
    // Simulate a request that takes longer than 10 seconds
    await page.evaluate(() => {
      return new Promise((resolve) => setTimeout(resolve, 12000));
    });

    const errorMessage = await page.getByText('Request timed out. Please try again.');
    await expect(errorMessage).toBeVisible();
  });

  test('should not display timeout error for requests under 10 seconds', async ({ page }) => {
    // Simulate a request that takes less than 10 seconds
    await page.evaluate(() => {
      return new Promise((resolve) => setTimeout(resolve, 5000));
    });

    const errorMessage = page.getByText('Request timed out. Please try again.');
    await expect(errorMessage).not.toBeVisible();
  });
});
